const imagePathCache=new Map<string,Promise<string>>()
;(globalThis as any).__ehentaiClearImageMemoryCache=()=>imagePathCache.clear()
const fileManager:any=(globalThis as any).FileManager
const PREVIEW_WIDTH=96, PREVIEW_HEIGHT=128, IMAGE_TIMEOUT_MS=15_000, MAX_IMAGE_REQUESTS=3
type ImageStage="detail-cover"|"home-thumbnail"|"preview-thumbnail"|"reader-image"
type PendingImageTask={stage:ImageStage;sequence:number;enqueuedAt:number;start:()=>void}
const IMAGE_PRIORITY:Record<ImageStage,number>={"home-thumbnail":0,"preview-thumbnail":1,"reader-image":2,"detail-cover":3}
const pendingImageTasks:PendingImageTask[]=[];let activeImageTasks=0;let imageTaskSequence=0
function drainImageTasks(){while(activeImageTasks<MAX_IMAGE_REQUESTS&&pendingImageTasks.length){pendingImageTasks.sort((a,b)=>IMAGE_PRIORITY[b.stage]-IMAGE_PRIORITY[a.stage]||a.sequence-b.sequence);pendingImageTasks.shift()?.start()}}
function enqueueImageTask<T>(stage:ImageStage,work:(queueMs:number)=>Promise<T>):Promise<T>{const enqueuedAt=Date.now();return new Promise((resolve,reject)=>{const start=()=>{activeImageTasks+=1;void work(Date.now()-enqueuedAt).then(resolve,reject).finally(()=>{activeImageTasks-=1;drainImageTasks()})};pendingImageTasks.push({stage,sequence:imageTaskSequence++,enqueuedAt,start});drainImageTasks()})}
function hashText(value:string){let hash=2166136261;for(let i=0;i<value.length;i++){hash^=value.charCodeAt(i);hash=Math.imul(hash,16777619)}return(hash>>>0).toString(16)}
function imageHost(url:string){try{return new URL(url).host}catch{return "invalid-host"}}
export function validCachedImagePayload(contentType:string,data:any){return isImagePayload(contentType,data)}
export function imageRequestCacheKey(url:string,stage:ImageStage,referer=""){return `${getAccountSessionGeneration()}|${stage}|${referer}|${url}`}
export async function cachedImagePath(url:string,stage:ImageStage,options?:any,refresh=false){
  const cacheKey=imageRequestCacheKey(url,stage,String(options?.headers?.Referer||""))
  const existing=imagePathCache.get(cacheKey);if(existing)return existing
  const task=enqueueImageTask(stage,async queueMs=>{const started=Date.now();let fetchStarted=0;let response:any
    try{const dir=`${Script.directory}/.image-cache`;await fileManager.createDirectory(dir,true);const ext=new URL(url).pathname.match(/\.(jpg|jpeg|png|webp)$/i)?.[1]?.toLowerCase()||"jpg";const path=`${dir}/${hashText(cacheKey)}.${ext}`
      try{if(refresh&&await fileManager.isFile(path))await fileManager.remove(path);if(!refresh&&await fileManager.isFile(path)){await reportSafe({stage,ok:true,request:{url,status:200,statusText:"cache"},notes:`host=${imageHost(url)}; queueMs=${queueMs}; fetchMs=0; totalMs=${queueMs+Date.now()-started}; contentType=cache; settle=cache-hit`});return path}}catch{}
      fetchStarted=Date.now();response=await fetch(url,{...(options||{}),signal:AbortSignal.timeout(stage==="reader-image"?20_000:IMAGE_TIMEOUT_MS)} as any);const contentType=String(response.headers?.get?.("content-type")||"");if(!response.ok)throw new Error(`HTTP ${response.status}`);const data=await response.data();if(!validCachedImagePayload(contentType,data))throw new Error("图片响应无效。");const fetchMs=Date.now()-fetchStarted;await fileManager.writeAsData(path,data)
      await reportSafe({stage,ok:true,request:{url,status:Number(response.status||0),statusText:String(response.statusText||"")},notes:`host=${imageHost(url)}; queueMs=${queueMs}; fetchMs=${fetchMs}; totalMs=${queueMs+Date.now()-started}; contentType=${contentType||"unknown"}; settle=written`});return path
    }catch(error){imagePathCache.delete(cacheKey);await reportSafe({stage,ok:false,error,request:{url,status:Number(response?.status||0),statusText:String(response?.statusText||"")},notes:`host=${imageHost(url)}; queueMs=${queueMs}; fetchMs=${fetchStarted?Date.now()-fetchStarted:0}; totalMs=${queueMs+Date.now()-started}; settle=failed`});throw error}
  });imagePathCache.set(cacheKey,task);return task
}
export function imageRequestOptions(url:string,referer=getBaseUrl()){const cookie=getCookieHeader(url);return{headers:{Accept:"image/webp,image/png,image/jpeg,image/*,*/*;q=0.8",Referer:referer,...(cookie?{Cookie:cookie}:{})}}}
function CachedThumbnail({url,stage,frame,cornerRadius}:{url:string;stage:"home-thumbnail"|"preview-thumbnail";frame:any;cornerRadius:number}){const[filePath,setFilePath]=useState("");const[error,setError]=useState("");useEffect(()=>{let cancelled=false;setFilePath("");setError("");void cachedImagePath(url,stage,imageRequestOptions(url)).then(path=>{if(!cancelled)setFilePath(path)}).catch(caught=>{if(!cancelled)setError("图片加载失败，请稍后重试")});return()=>{cancelled=true}},[url,stage]);if(error)return <Image systemName="exclamationmark.triangle" frame={frame} foregroundStyle="systemOrange"/>;if(!filePath)return <ProgressView progressViewStyle="circular" frame={frame}/>;return <Image filePath={filePath} resizable scaleToFill frame={frame} clipShape={{type:"rect",cornerRadius}}/>}
function PreviewThumbnail({page}:{page:GalleryPageLink}){const sprite=Boolean(page.thumb&&page.thumbWidth>0&&page.thumbHeight>0);if(!page.thumb)return <Image systemName="photo" frame={{width:PREVIEW_WIDTH,height:PREVIEW_HEIGHT}} foregroundStyle="secondaryLabel"/>;if(!sprite)return <CachedThumbnail url={page.thumb} stage="preview-thumbnail" frame={{width:PREVIEW_WIDTH,height:PREVIEW_HEIGHT}} cornerRadius={7}/>;return <SpritePreview page={page}/>}
function SpritePreview({page}:{page:GalleryPageLink}){const[filePath,setFilePath]=useState("");const[error,setError]=useState("");useEffect(()=>{let cancelled=false;void cachedImagePath(page.thumb,"preview-thumbnail",imageRequestOptions(page.thumb)).then(path=>{if(!cancelled)setFilePath(path)}).catch(()=>{if(!cancelled)setError("图片加载失败，请稍后重试")});return()=>{cancelled=true}},[page.thumb]);if(error)return <Image systemName="exclamationmark.triangle" frame={{width:PREVIEW_WIDTH,height:PREVIEW_HEIGHT}} foregroundStyle="systemOrange"/>;if(!filePath)return <ProgressView progressViewStyle="circular" frame={{width:PREVIEW_WIDTH,height:PREVIEW_HEIGHT}}/>;return <Canvas frame={{width:PREVIEW_WIDTH,height:PREVIEW_HEIGHT}} draw={(ctx:any,size:any)=>{ctx.fillStyle="systemGray6";ctx.fillRect(0,0,size.width,size.height);const sw=Math.max(1,page.thumbWidth),sh=Math.max(1,page.thumbHeight),scale=Math.min(size.width/sw,size.height/sh),dw=sw*scale,dh=sh*scale;ctx.drawImage({filePath},page.thumbX,page.thumbY,sw,sh,(size.width-dw)/2,(size.height-dh)/2,dw,dh)}}/>}
function CachedReaderImage({url,referer,fit="width",onLoaded,onTap}:{url:string;referer:string;fit?:ReaderPreferences["fit"];onLoaded?:()=>void;onTap?:()=>void}){const[filePath,setFilePath]=useState("");const[error,setError]=useState("");const[retry,setRetry]=useState(0);useEffect(()=>{let cancelled=false;setFilePath("");setError("");const cookie=getCookieHeader(url);void cachedImagePath(url,"reader-image",{headers:{Accept:"image/webp,image/png,image/jpeg,image/*,*/*;q=0.8",Referer:referer,...(cookie?{Cookie:cookie}:{})}},retry>0).then(path=>{if(!cancelled){setFilePath(path);onLoaded?.()}}).catch(()=>{if(!cancelled)setError("图片加载失败或超时，请稍后重试")});return()=>{cancelled=true}},[url,referer,retry]);if(error)return <VStack spacing={6}>{error?<ErrorText message={error}/>:null}<Button title="重试图片" buttonStyle="bordered" action={()=>setRetry(value=>value+1)}/></VStack>;if(!filePath)return <ProgressView title="加载图片…" progressViewStyle="circular"/>;const image=<Image filePath={filePath} resizable scaleToFit frame={fit==="screen"?{maxWidth:"infinity",height:620}:{maxWidth:"infinity"}}/>;return onTap?<Button buttonStyle="plain" action={onTap}>{image}</Button>:image}
function ContinuousReaderImage({page,preferOriginal,fit,onTap,onLoaded}:{page:GalleryPageLink;preferOriginal:boolean;fit:ReaderPreferences["fit"];onTap:()=>void;onLoaded?:()=>void}){const[resolved,setResolved]=useState<{url:string;referer:string}|null>(null);const[error,setError]=useState("");const[retry,setRetry]=useState(0);useEffect(()=>{let cancelled=false;setResolved(null);setError("");void resolveImagePage(page.pageUrl,retry>0).then(value=>{if(!cancelled)setResolved({url:preferOriginal&&value.originalUrl?value.originalUrl:value.imageUrl,referer:value.pageUrl})}).catch(()=>{if(!cancelled)setError("图片地址解析失败，请重试")});return()=>{cancelled=true}},[page.pageUrl,preferOriginal,retry]);return <VStack spacing={8} frame={{maxWidth:"infinity"}}><Text font="caption" foregroundStyle="secondaryLabel">第 {page.index} 页</Text>{resolved?<CachedReaderImage url={resolved.url} referer={resolved.referer} fit={fit} onTap={onTap} onLoaded={onLoaded}/>:error?<VStack spacing={6}>{error?<ErrorText message={error}/>:null}<Button title="重试本页" buttonStyle="bordered" action={()=>setRetry(value=>value+1)}/></VStack>:<ProgressView title="加载图片…" progressViewStyle="circular"/>}</VStack>}
export function detailCoverRequestOptions(url:string,detailUrl:string){return imageRequestOptions(url,detailUrl)}
const downloadPreparedLabel=(item:OfflineDownload)=>item.scope==="all"&&!inventoryIsComplete(item)?`已准备 ${item.pages.length} / ${item.totalPages} 页`:"";
function DetailCover({url,referer,frame}:{url:string;referer:string;frame?:any}){const[filePath,setFilePath]=useState(""),[error,setError]=useState(""),[retry,setRetry]=useState(0),coverFrame=frame||{maxWidth:"infinity",height:280};useEffect(()=>{let cancelled=false;setFilePath("");setError("");void cachedImagePath(url,"detail-cover",detailCoverRequestOptions(url,referer),retry>0).then(path=>{if(!cancelled)setFilePath(path)}).catch(()=>{if(!cancelled)setError("封面加载失败或超时")});return()=>{cancelled=true}},[url,referer,retry]);if(error)return <VStack spacing={6} frame={coverFrame}><Image systemName="photo" frame={{width:72,height:72}} foregroundStyle="secondaryLabel"/><Text font="caption" foregroundStyle="secondaryLabel" lineLimit={2}>{error}</Text><Button title="重试封面" buttonStyle="bordered" action={()=>setRetry(value=>value+1)}/></VStack>;if(!filePath)return <VStack spacing={8} frame={coverFrame}><ProgressView title="加载封面…" progressViewStyle="circular"/></VStack>;return <Image filePath={filePath} resizable scaleToFit frame={coverFrame} clipShape={{type:"rect",cornerRadius:12}}/>}
