export function GalleryCard({item,note=""}:{item:GallerySummary;note?:string}){return <GlassSurface padding={9}><VStack alignment="leading" spacing={7} frame={{maxWidth:"infinity",alignment:"leading"}}>{item.thumb?<CachedThumbnail url={item.thumb} stage="home-thumbnail" frame={{maxWidth:"infinity",height:190}} cornerRadius={10}/>:<Image systemName="photo" frame={{maxWidth:"infinity",height:190}} foregroundStyle="secondaryLabel"/>}<Text font="subheadline" fontWeight="semibold" lineLimit={3}>{item.title||"未命名画廊"}</Text>{item.category?<Text font="caption" padding={{horizontal:8,vertical:3}} background="secondarySystemBackground" clipShape={{type:"rect",cornerRadius:7}}>{localizeCategory(item.category)}</Text>:null}<GalleryMetadata item={item}/>{note?<Text font="caption" foregroundStyle="systemBlue" lineLimit={2}>{note}</Text>:null}</VStack></GlassSurface>}
export function LibraryGalleryGrid({items,noteForItem}:{items:GallerySummary[];noteForItem?:(item:GallerySummary)=>string}){const[selected,setSelected]=useState<GallerySummary|null>(null);return <EnvironmentValuesReader keys={["horizontalSizeClass"]}>{environment=><LazyVGrid columns={Array.from({length:galleryGridColumnCount(environment.horizontalSizeClass)},()=>({size:{type:"flexible" as const}}))} alignment="leading" spacing={12} navigationDestination={{isPresented:Boolean(selected),onChanged:presented=>{if(!presented)setSelected(current=>selectGallery(current,null))},content:selected?<GalleryDetailView summary={selected}/>:<VStack/>}}>{items.map(item=><Button key={galleryIdentity(item)} buttonStyle="plain" action={()=>setSelected(current=>selectGallery(current,item))}>{environment.horizontalSizeClass==="compact"?<VStack alignment="leading" spacing={5} frame={{maxWidth:"infinity"}}><GalleryRow item={item}/>{noteForItem?.(item)?<Text font="caption" foregroundStyle="systemBlue" lineLimit={1}>{noteForItem?.(item)}</Text>:null}</VStack>:<GalleryCard item={item} note={noteForItem?.(item)||""}/>}</Button>)}</LazyVGrid>}</EnvironmentValuesReader>}
export function GalleryGrid({items}:{items:GallerySummary[]}){const[selected,setSelected]=useState<GallerySummary|null>(null);return <EnvironmentValuesReader keys={["horizontalSizeClass"]}>{environment=><LazyVGrid columns={environment.horizontalSizeClass==="compact"?[{size:{type:"flexible"}}]:[{size:{type:"flexible"}},{size:{type:"flexible"}},{size:{type:"flexible"}}]} alignment="leading" spacing={12} navigationDestination={{isPresented:Boolean(selected),onChanged:presented=>{if(!presented)setSelected(current=>selectGallery(current,null))},content:selected?<GalleryDetailView summary={selected}/>:<VStack/>}}>{items.map(item=><Button key={galleryIdentity(item)} buttonStyle="plain" action={()=>setSelected(current=>selectGallery(current,item))}><GalleryRow item={item}/></Button>)}</LazyVGrid>}</EnvironmentValuesReader>}
async function reportSafe(input:Parameters<typeof reportDiagnostic>[0]){try{await reportDiagnostic(input)}catch{}}

function AITagChooser({pending,onDone}:{pending:{state:GallerySearchState;ambiguous:AITagCandidate[]};onDone:(state:GallerySearchState)=>void}){const[index,setIndex]=useState(0),current=pending.ambiguous[index];const choose=(tags:GallerySearchTag[])=>{const next=current.exclude?composeGallerySearchState(pending.state,composeExcludedGalleryTags(pending.state.keyword,tags),pending.state.selectedTags):composeGallerySearchState(pending.state,pending.state.keyword,[...pending.state.selectedTags,...tags]);if(index+1>=pending.ambiguous.length)onDone(next);else{pending.state=next;setIndex(value=>value+1)}};return <List navigationTitle="确认 AI 标签"><Section header={<Text textCase={null}>{current.exclude?"排除":"包含"}：{current.concept}</Text>}><Text font="caption" foregroundStyle="secondaryLabel">这个中文概念有多个合法标签，请选择；不会随机代选。</Text>{current.options.map(option=><Button key={`${option.namespace}:${option.tag}`} title={`${option.display} · ${option.namespace}:${option.tag}`} action={()=>choose([option])}/>) }<Button title="全部选择" buttonStyle="bordered" action={()=>choose(current.options)}/><Button title="跳过此概念" action={()=>choose([])}/></Section></List>}
function AISearchFlow(){const[result,setResult]=useState<GallerySearchState|null>(null),[pending,setPending]=useState<{state:GallerySearchState;ambiguous:AITagCandidate[]}|null>(null),[loading,setLoading]=useState(false),[error,setError]=useState("");useEffect(()=>{void (async()=>{const input=await prompt({title:"✨ AI 搜索",message:"描述想找的内容。文本会发送到你在 Scripting 中配置的 Assistant 模型；不会发送 Cookie 或画廊私密 URL。",placeholder:"中文女性性转，30 到 80 页，排除 AI 生成",confirmLabel:"解析搜索"});if(!input)return;setLoading(true);try{const value=await requestAISearch(input);if(value.normalized.ambiguous.length)setPending({state:value.normalized.state,ambiguous:value.normalized.ambiguous});else setResult(value.normalized.state);if(value.normalized.unresolved.length)setError(`未识别标签已忽略：${value.normalized.unresolved.join("、")}`)}catch(e){setError(e instanceof Error?e.message:"AI 搜索解析失败，请重试。")}finally{setLoading(false)}})()},[]);if(result)return <ResultsView initial={result}/>;if(pending)return <AITagChooser pending={pending} onDone={setResult}/>;return <List navigationTitle="AI 搜索" overlay={loading?<ProgressView title="正在解析搜索意图…" progressViewStyle="circular"/>:undefined}><Section>{error?<ErrorText message={error}/>:<Text font="caption" foregroundStyle="secondaryLabel">完成后会进入普通搜索结果，可继续筛选并保存搜索书签。</Text>}</Section></List>}
function AIRecommendationFlow(){const[retry,setRetry]=useState(0),[items,setItems]=useState<GallerySummary[]>([]),[reasons,setReasons]=useState<Record<string,string>>({}),[loading,setLoading]=useState(false),[error,setError]=useState(""),[empty,setEmpty]=useState(false);useEffect(()=>{let cancelled=false;const generation=getAccountSessionGeneration();void (async()=>{const preference=await prompt({title:"✨ AI 推荐",message:"输入偏好。脚本会先执行真实站内搜索，再仅把有限候选的安全元数据交给 Assistant 排序；不会发送 Cookie、URL 或画廊标识。",placeholder:"帮我找带设备进入虚拟世界/VRMMO 设定的本子，标题不一定有 VR",confirmLabel:"搜索并推荐"});if(!preference)return;setLoading(true);setError("");setEmpty(false);setItems([]);setReasons({});try{const plans=await requestAIRecommendationPlans(preference);if(plans.some(plan=>plan.ambiguous.length))throw new Error("推荐条件中有歧义标签，请先用 ✨ AI 搜索确认后再推荐。");const pages=await Promise.all(plans.map(plan=>searchGalleries("",buildGallerySearchUrl(getBaseUrl(),plan.state))));if(cancelled||generation!==getAccountSessionGeneration())return;const candidates=[...new Map(pages.flatMap(page=>page.items).map(item=>[galleryIdentity(item),item])).values()].slice(0,12);if(!candidates.length){setEmpty(true);return}const details=await Promise.all(candidates.map(async(item,index)=>{const detail=await loadGalleryDetailCore(routeUrlForSite(item.url));return{item,candidate:{candidateId:`c${index}`,title:detail.title||item.title,titleJpn:detail.titleJpn||"",category:detail.category||item.category,uploader:detail.uploader||item.uploader,pageCount:galleryPageCount(detail)||item.pages,rating:detail.rating,ratingCount:detail.ratingCount,tags:detail.tags.flatMap(group=>group.tags.map(tag=>`${group.namespace}:${tag.name}`)).slice(0,20)} as SafeRecommendationCandidate}}));if(cancelled||generation!==getAccountSessionGeneration())return;const ranked=await rankRecommendationCandidates(preference,details.map(value=>value.candidate));if(cancelled||generation!==getAccountSessionGeneration())return;const byId=new Map(details.map(value=>[value.candidate.candidateId,value]));const selected=ranked.map(rank=>({rank,value:byId.get(rank.candidateId)})).filter((entry):entry is {rank:typeof ranked[number];value:typeof details[number]}=>Boolean(entry.value));setItems(selected.map(entry=>entry.value.item));setReasons(Object.fromEntries(selected.map(entry=>[galleryIdentity(entry.value.item),entry.rank.reason])));setEmpty(!selected.length)}catch(e){if(!cancelled&&generation===getAccountSessionGeneration())setError(e instanceof Error?e.message:"AI 推荐失败，请重试。")}finally{if(!cancelled&&generation===getAccountSessionGeneration())setLoading(false)}})();return()=>{cancelled=true}},[retry]);return <List navigationTitle="AI 推荐" overlay={loading?<ProgressView title="正在真实搜索并排序候选…" progressViewStyle="circular"/>:undefined} background={<PageBackground/>}><Section header={<Text textCase={null}>真实候选</Text>} footer={<Text>结果来自当前站点真实搜索；推荐理由只基于有限候选的标题、分类、页数、评分、上传者和标签。</Text>}>{error?<ErrorText message={error}/>:null}{items.length?<LibraryGalleryGrid items={items} noteForItem={item=>reasons[galleryIdentity(item)]||""}/>:null}{empty&&!loading?<EmptyState message="没有找到符合条件的结果。可放宽条件后重试。"/>:null}{(empty||error)&&!loading?<Button title="放宽条件重试" buttonStyle="bordered" action={()=>setRetry(value=>value+1)}/>:null}</Section></List>}
function SearchComposer({initial}:{initial:GallerySearchState}){const[state,setState]=useState(cloneSearchState(initial)),[input,setInput]=useState(initial.keyword),[suggestions,setSuggestions]=useState(searchLocalTagSuggestions(initial.keyword)),[translationStatus,setTranslationStatus]=useState(getTagTranslationStatus()),[notice,setNotice]=useState(""),[actionError,setActionError]=useState(""),inputRef=useRef(initial.keyword);useEffect(()=>{let cancelled=false;void ensureTagTranslations().then(()=>{if(cancelled)return;setTranslationStatus(getTagTranslationStatus());setSuggestions(searchLocalTagSuggestions(inputRef.current))});return()=>{cancelled=true}},[]);const changeText=(value:string)=>{inputRef.current=value;setInput(value);setSuggestions(searchLocalTagSuggestions(value));setState(current=>composeGallerySearchState(current,value,current.selectedTags||[]))};const select=(value:{namespace:string;tag:string;translated:string})=>{const tag=createGallerySearchTag(value.namespace,value.tag,value.translated);if(!tag)return;inputRef.current="";setInput("");setSuggestions([]);setState(current=>selectGallerySearchTag(current,tag));};const remove=(tag:GallerySearchTag)=>setState(current=>removeGallerySearchTag(current,tag));const save=async()=>{setNotice("");setActionError("");try{await saveSearch(state);setNotice("已保存当前完整搜索条件。") }catch(error){setActionError(error instanceof Error?error.message:"保存搜索失败。")}};return <VStack alignment="leading" spacing={9} frame={{maxWidth:"infinity"}}><TextField title="搜索画廊" value={input} onChanged={changeText} prompt="标题、作者、中文或英文标签…" submitLabel="search"/>{state.selectedTags.length?<ScrollView axes="horizontal"><HStack spacing={7}>{state.selectedTags.map(tag=><Button key={`${tag.namespace}:${tag.tag}`} title={`${tag.display} ×`} buttonStyle="bordered" action={()=>remove(tag)}/>)}</HStack></ScrollView>:null}{suggestions.length?<VStack alignment="leading" spacing={5}>{suggestions.slice(0,8).map(item=><Button key={`${item.namespace}:${item.tag}`} title={`${item.namespace}:${item.tag} / ${item.translated}`} action={()=>select(item)}/>)}</VStack>:null}<HStack spacing={10}><NavigationLink destination={<ResultsView initial={state}/>} disabled={!state.rawQuery.trim()}><Text>搜索</Text></NavigationLink><NavigationLink destination={<HomeFilterEntry initial={state}/>}><Text>+ 高级筛选</Text></NavigationLink><Button title="保存搜索" disabled={!state.rawQuery.trim()&&!state.selectedTags.length} action={()=>void save()}/><NavigationLink destination={<QuickSearchScene/>}><Text>搜索书签</Text></NavigationLink></HStack><GlassActionGroup><HStack spacing={10}><GlassActionButton title="✨ AI 搜索" systemImage="sparkles" fullWidth={false} destination={<AISearchFlow/>}/><GlassActionButton title="✨ AI 推荐" systemImage="sparkles" fullWidth={false} destination={<AIRecommendationFlow/>}/></HStack></GlassActionGroup>{actionError?<ErrorText message={actionError}/>:null}{notice?<Text font="caption" foregroundStyle="systemGreen">{notice}</Text>:null}{state.rawQuery?<Text font="caption" foregroundStyle="secondaryLabel">{state.rawQuery}</Text>:null}<Text font="caption" foregroundStyle={translationStatus.fullDatabaseLoaded?"secondaryLabel":"systemOrange"}>{translationStatus.fullDatabaseLoaded?`完整标签库 ${translationStatus.count} 条 · ${translationStatus.source}`:translationStatus.error?`标签库加载失败：${translationStatus.error}`:"正在加载完整标签库…"}</Text></VStack>}

export function SearchScene(){return <List navigationTitle="搜索" navigationBarTitleDisplayMode="large" background={<PageBackground/>}><Section><SearchComposer initial={createHomeSearchState()}/></Section><Section footer={<Text>标签建议来自本地翻译库；已选标签使用 E-Hentai 精确标签语法。</Text>}><NavigationLink destination={<QuickSearchScene/>}><Text>已保存的快速搜索</Text></NavigationLink></Section></List>}

function FilterView({ initial, onApply, dismissAfterApply = true }: {
  initial: GallerySearchState
  onApply: (state: GallerySearchState) => void
  dismissAfterApply?: boolean
}) {
  const dismiss = Navigation.useDismiss()
  const [excludedCategoryMask, setExcludedCategoryMask] = useState(initial.excludedCategoryMask)
  const [quick, setQuick] = useState<QuickFilterKey>(initial.quickFilter)
  const [advanced, setAdvanced] = useState(initial.advanced)
  const apply = () => {
    onApply({ ...cloneSearchState(initial), excludedCategoryMask, quickFilter: quick, advanced })
    if (dismissAfterApply) dismiss()
  }
  return <List navigationTitle="搜索筛选" navigationBarTitleDisplayMode="inline">
    <Section header={<Text textCase={null}>分类</Text>}><VStack alignment="leading" spacing={9}><Text font="caption" foregroundStyle="secondaryLabel">点按可排除分类；变暗 = 排除</Text><Button title="全部包含" buttonStyle={excludedCategoryMask===0?"borderedProminent":"bordered"} action={()=>setExcludedCategoryMask(0)}/><LazyVGrid columns={[{size:{type:"adaptive",min:96,max:160}}]} alignment="leading" spacing={8}>{GALLERY_CATEGORIES.filter(item=>item.bit).map(item=>{const excluded=(excludedCategoryMask&item.bit)!==0;return <Button key={item.key} title={item.label} buttonStyle={excluded?"bordered":"borderedProminent"} opacity={excluded?0.45:1} action={()=>setExcludedCategoryMask(mask=>toggleExcludedCategory(mask,item.bit))}/>})}</LazyVGrid></VStack></Section>
    <Section header={<Text textCase={null}>语言与常用筛选</Text>}><VStack alignment="leading" spacing={7}>{QUICK_FILTERS.map(item => <Button key={item.key} title={`${quick === item.key ? "✓ " : ""}${item.label}`} buttonStyle={quick === item.key ? "borderedProminent" : "bordered"} action={() => setQuick(item.key)} />)}</VStack></Section>
    <Section header={<Text textCase={null}>高级搜索</Text>}><Button title={advanced.enabled ? "关闭高级搜索" : "启用高级搜索"} buttonStyle={advanced.enabled ? "borderedProminent" : "bordered"} action={() => setAdvanced({ ...advanced, enabled: !advanced.enabled })} />{advanced.enabled ? <VStack alignment="leading" spacing={8}><Button title={`${advanced.searchName ? "✓" : "○"} 搜索画廊名称`} action={() => setAdvanced({ ...advanced, searchName: !advanced.searchName })} /><Button title={`${advanced.searchTags ? "✓" : "○"} 搜索画廊标签`} action={() => setAdvanced({ ...advanced, searchTags: !advanced.searchTags })} /><Button title={`${advanced.searchDescription ? "✓" : "○"} 搜索画廊描述`} action={() => setAdvanced({ ...advanced, searchDescription: !advanced.searchDescription })} /><VStack alignment="leading" spacing={8}><Text font="caption">最低评分</Text><LazyVGrid columns={[{size:{type:"adaptive",min:64,max:96}}]} alignment="leading" spacing={8}>{(["","2","3","4","5"] as const).map(value=><Button key={value||"any"} title={value?`${value}+`:"不限"} buttonStyle={advanced.minimumRating===value?"borderedProminent":"bordered"} action={()=>setAdvanced({...advanced,minimumRating:value})}/>)}</LazyVGrid></VStack><HStack spacing={8}><TextField title="最少页数" value={advanced.pageFrom} onChanged={pageFrom=>setAdvanced({...advanced,pageFrom:pageFrom.replace(/\D/g,"")})} prompt="最少" keyboardType="numberPad"/><TextField title="最多页数" value={advanced.pageTo} onChanged={pageTo=>setAdvanced({...advanced,pageTo:pageTo.replace(/\D/g,"")})} prompt="最多" keyboardType="numberPad"/></HStack><Button title={`${advanced.searchTorrents?"✓":"○"} 仅含种子`} action={()=>setAdvanced({...advanced,searchTorrents:!advanced.searchTorrents})}/><Button title={`${advanced.searchTorrentFilenames?"✓":"○"} 搜索种子文件名`} action={()=>setAdvanced({...advanced,searchTorrentFilenames:!advanced.searchTorrentFilenames})}/><Button title={`${advanced.searchLowPowerTags?"✓":"○"} 搜索低权重标签`} action={()=>setAdvanced({...advanced,searchLowPowerTags:!advanced.searchLowPowerTags})}/><Button title={`${advanced.searchDownvotedTags?"✓":"○"} 搜索被否决标签`} action={()=>setAdvanced({...advanced,searchDownvotedTags:!advanced.searchDownvotedTags})}/><Button title={`${advanced.disableLanguageFilter?"✓":"○"} 禁用默认语言过滤`} action={()=>setAdvanced({...advanced,disableLanguageFilter:!advanced.disableLanguageFilter})}/><Button title={`${advanced.disableUploaderFilter?"✓":"○"} 禁用默认上传者过滤`} action={()=>setAdvanced({...advanced,disableUploaderFilter:!advanced.disableUploaderFilter})}/><Button title={`${advanced.disableTagFilter?"✓":"○"} 禁用默认标签过滤`} action={()=>setAdvanced({...advanced,disableTagFilter:!advanced.disableTagFilter})}/><Button title={`${advanced.showExpunged?"✓":"○"} 显示已删除`} action={()=>setAdvanced({...advanced,showExpunged:!advanced.showExpunged})}/></VStack> : null}</Section>
    <Section><Button title="应用筛选" buttonStyle="borderedProminent" action={apply} /></Section>
  </List>
}

function ResultsView({ initial }: { initial: GallerySearchState }) {
  const [state, setState] = useState(cloneSearchState(initial))
  const [items, setItems] = useState<GallerySummary[]>([])
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState("")
  const [resultCount, setResultCount] = useState("")
  const [prev, setPrev] = useState("")
  const [next, setNext] = useState("")
  const requestEpoch = useRef(0),requestController=useRef<AbortController|null>(null)
  const load = async (direct?: string, nextState: GallerySearchState = state) => {
    requestController.current?.abort();const controller=new AbortController();requestController.current=controller
    const epoch = ++requestEpoch.current, generation=getAccountSessionGeneration()
    setLoading(true);setError("");setItems([]);setResultCount("");setPrev("");setNext("")
    const url = direct ? routeUrlForSite(direct) : buildGallerySearchUrl(getBaseUrl(), nextState)
    try {
      const page = await searchGalleries("", url, controller.signal)
      if (epoch !== requestEpoch.current || generation!==getAccountSessionGeneration()) return
      setItems(page.items); setResultCount(page.resultCount); setPrev(page.prevHref); setNext(page.nextHref)
      await reportSafe({ stage: "gallery-search-filter", ok: true, request: { url: page.url }, notes: `items=${page.items.length}; excludedMask=${nextState.excludedCategoryMask}; tagPresent=${nextState.mode === "tag"}` })
    } catch (caught) {
      if (epoch !== requestEpoch.current || generation!==getAccountSessionGeneration()) return
      setError(caught instanceof Error ? caught.message : String(caught)); setItems([]);setResultCount("");setPrev("");setNext("")
    } finally {
      if (epoch === requestEpoch.current && requestController.current===controller) setLoading(false)
    }
  }
  useEffect(() => { void load(undefined, initial); return()=>{requestEpoch.current+=1;requestController.current?.abort()} }, [getAccountSessionGeneration()])
  const apply = (value: GallerySearchState) => { setState(value); setPrev(""); setNext(""); void load(undefined, value) }
  return <List navigationTitle={searchTitle(state)} navigationBarTitleDisplayMode="inline" overlay={loading ? <ProgressView title="正在搜索…" progressViewStyle="circular" /> : undefined} background={<PageBackground/>}>
    <Section><HStack><VStack alignment="leading" spacing={3}><Text font="headline">{searchTitle(state)}</Text>{searchRawQuery(state) ? <Text font="caption" foregroundStyle="secondaryLabel">{searchRawQuery(state)}</Text> : null}<Text font="caption" foregroundStyle="secondaryLabel">{categoryExclusionSummary(state.excludedCategoryMask)} · {getQuickFilter(state.quickFilter).label}</Text></VStack><Spacer /><Button title="保存搜索" action={()=>void saveSearch(state).catch(()=>{})}/><NavigationLink destination={<QuickSearchScene/>}><Text>搜索书签</Text></NavigationLink><NavigationLink destination={<FilterView initial={state} onApply={apply} />}><Text>筛选</Text></NavigationLink></HStack>{error?<ErrorText message={error}/>:null}</Section>
    <Section header={<Text textCase={null}>{[resultCount ? `结果 ${resultCount}` : "", items.length ? `本页 ${items.length} 条` : ""].filter(Boolean).join(" · ") || "搜索结果"}</Text>}><GalleryGrid items={items}/>{!loading && !error && items.length === 0 ? <EmptyState message="没有找到匹配的画廊。可调整搜索词或筛选条件后重试。" /> : null}{error ? <Button title="重试搜索" buttonStyle="bordered" action={() => { void load() }} /> : null}</Section>
    {prev || next ? <Section footer={<Text>浏览更多结果</Text>}><HStack><Button title="上一页" systemImage="chevron.left" buttonStyle="bordered" disabled={!prev || loading} action={() => { if (prev) void load(prev) }} /><Spacer /><Button title="下一页" systemImage="chevron.right" buttonStyle="bordered" disabled={!next || loading} action={() => { if (next) void load(next) }} /></HStack></Section> : null}
  </List>
}

export function ImageSearchScene(){const[items,setItems]=useState<GallerySummary[]>([]),[loading,setLoading]=useState(false),[error,setError]=useState(""),epoch=useRef(0);useEffect(()=>()=>{epoch.current+=1},[]);const run=async(coversOnly=false)=>{if(loading)return;const current=++epoch.current;setLoading(true);setError("");try{const picked=await Photos.pickPhotos(1),data=picked[0]?Data.fromJPEG(picked[0],.9):null;if(!data)throw new Error("无法读取所选图片。");const page=await imageSearch(data,{similar:true,coversOnly,showExpunged:true});if(current===epoch.current)setItems(page.items)}catch(e){if(current===epoch.current)setError(e instanceof Error?e.message:"图片搜索失败")}finally{if(current===epoch.current)setLoading(false)}};return <List navigationTitle="图片搜索" overlay={loading?<ProgressView title="正在上传并搜索…" progressViewStyle="circular"/>:undefined}><Section><Text font="caption" foregroundStyle="secondaryLabel">从照片中选择一张图片，使用 E-Hentai 图片搜索协议。图片仅发送到当前 E/Ex 搜索服务。</Text><HStack><Button title="相似图片搜索" buttonStyle="borderedProminent" disabled={loading} action={()=>void run(false)}/><Button title="仅搜索封面" buttonStyle="bordered" disabled={loading} action={()=>void run(true)}/></HStack>{error?<ErrorText message={error}/>:null}</Section><Section header={<Text textCase={null}>搜索结果 · {items.length}</Text>}><GalleryGrid items={items}/>{!loading&&!error&&!items.length?<EmptyState message="选择图片后，结果会复用现有画廊列表和详情流程。"/>:null}</Section></List>}
function CoverSearchScene({coverUrl,referer}:{coverUrl:string;referer:string}){const[items,setItems]=useState<GallerySummary[]>([]),[loading,setLoading]=useState(true),[error,setError]=useState("");useEffect(()=>{let cancelled=false;void cachedImagePath(coverUrl,"detail-cover",detailCoverRequestOptions(coverUrl,referer)).then(path=>imageSearch(path,{similar:true,coversOnly:true,showExpunged:true})).then(page=>{if(!cancelled)setItems(page.items)}).catch(e=>{if(!cancelled)setError(e instanceof Error?e.message:"封面搜索失败")}).finally(()=>{if(!cancelled)setLoading(false)});return()=>{cancelled=true}},[coverUrl,referer]);return <List navigationTitle="搜索封面" overlay={loading?<ProgressView title="正在搜索封面…" progressViewStyle="circular"/>:undefined}><Section>{error?<ErrorText message={error}/>:null}<GalleryGrid items={items}/>{!loading&&!error&&!items.length?<EmptyState message="没有找到相似封面。"/>:null}</Section></List>}
function HomeFilterEntry({ initial }: { initial: GallerySearchState }) {
  const [result, setResult] = useState<GallerySearchState | null>(null)
  return result ? <ResultsView initial={result} /> : <FilterView initial={initial} onApply={setResult} dismissAfterApply={false} />
}

function AccountSection({ account, onAccountContextChanged }: { account: ReturnType<typeof getAccountStatus>; onAccountContextChanged: (status: ReturnType<typeof getAccountStatus>) => void }) {
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState("")
  const [notice, setNotice] = useState("")
  const updateContext = (status: ReturnType<typeof getAccountStatus>) => onAccountContextChanged(status)
  const run = async (action: "manual" | "safari" | "ex-sync" | "import" | "refresh" | "logout" | "e" | "ex") => {
    if (busy) return
    setBusy(true); setError(""); setNotice("")
    try {
      if (action === "manual") {
        const text=String(await Pasteboard.getString()||"").trim();if(!text)throw new Error("剪贴板中没有文本。请先复制三行 Cookie；如系统询问粘贴权限请选择允许。")
        const summary=manualCookieSummary(text);if(!summary.memberIdPresent||!summary.passHashPresent)throw new Error("剪贴板未同时识别到 ipb_member_id 和 ipb_pass_hash；不会保存任何内容。")
        const targetName=summary.target==="ex"?"ExHentai":"E-Hentai",approved=await confirm({title:`从剪贴板导入 ${targetName}？`,message:`已识别：member id ✓ · pass hash ✓ · igneous ${summary.igneousStructurallyValid?"✓":"无"}。不会显示、记录或上传 Cookie 值；确认后执行真实登录验证。`,confirmLabel:"验证并保存",cancelLabel:"取消"});if(!approved)return
        const result=await saveAndValidateManualCookie(text),status=result.status;updateContext(status);setNotice(result.target==="ex"?"已从剪贴板识别 igneous，并验证、切换到 ExHentai。":"剪贴板未包含 igneous，已按 E-Hentai 登录验证。")
      } else if (action === "safari") {
        await openSafariLogin();setNotice("已打开 Safari。登录后点击页面左下角 Cookie 助手，或在 Scripting 扩展菜单选择“获取 EH Cookie 并写入”，再返回此处导入。")
      } else if (action === "ex-sync") {
        await openSafariExSync();setNotice("已打开真实 ExHentai。确认页面可访问后点击 Cookie 助手，再返回此处导入；会合并真实 E/Ex Cookie，不会跨域复制。")
      } else if (action === "import") {
        const status=await importAndValidateBrowserCookies();updateContext(status);setNotice(status.exAvailable?"已导入并验证 E-Hentai / ExHentai 登录。":"已验证 E-Hentai 登录；当前账户暂不可使用 ExHentai。")
      } else if (action === "refresh") updateContext(await refreshAccountStatus())
      else if (action === "logout") { try { await signOut() } finally { updateContext(getAccountStatus()) } }
      else { setActiveSite(action); updateContext(getAccountStatus()) }
    } catch (caught) { setError(caught instanceof Error ? caught.message : String(caught)) }
    finally { setBusy(false) }
  }
  return <>
    <Section header={<Text textCase={null}>登录状态</Text>}><VStack alignment="leading" spacing={7}>
      <Text font="headline">{account.loggedIn ? account.eHentaiReachable&&account.exAvailable?"E-Hentai / ExHentai 已登录":account.exAvailable?"ExHentai 已登录":"E-Hentai 已登录":"游客模式"}</Text>
      <Text font="caption" foregroundStyle="secondaryLabel">E-Hentai：{account.eHentaiReachable===true?"可用":account.eHentaiReachable===false?"验证失败":"待检测"} · ExHentai：{account.exAvailable===true?"可用":account.exAvailable===false?"不可用":"待检测"}</Text>
      <Text font="caption" foregroundStyle="secondaryLabel">Cookie 仅保存在本机 Keychain，不会写入日志或仓库。</Text>
    </VStack></Section>
    <Section header={<Text textCase={null}>登录</Text>}><VStack alignment="leading" spacing={10}>
      <Button title="在 Safari 登录" buttonStyle="bordered" disabled={busy} action={() => { void run("safari") }} />
      <Button title="同步里站登录" buttonStyle="bordered" disabled={busy || !account.loggedIn} action={() => { void run("ex-sync") }} />
      <Button title="导入并验证登录状态" buttonStyle="borderedProminent" disabled={busy} action={() => { void run("import") }} />
      <Text font="caption" foregroundStyle="secondaryLabel">Safari 登录后点击左下角 Cookie 助手；也可从 Scripting 扩展菜单选择“获取 EH Cookie 并写入”。返回 App 后点击导入并验证。</Text>
      {busy ? <ProgressView progressViewStyle="circular" /> : null}{notice?<Text font="caption" foregroundStyle="systemGreen">{notice}</Text>:null}{error?<ErrorText message={error}/>:null}
    </VStack></Section>
    {account.loggedIn?<Section header={<Text textCase={null}>站点</Text>}><VStack alignment="leading" spacing={7}><Text font="caption" foregroundStyle="secondaryLabel">当前站点以蓝色标记；灰色按钮仅表示尚未具备该站点可用凭据。</Text><HStack spacing={8}>{account.site === "e"?<Text font="caption" foregroundStyle="white" padding={{horizontal:10,vertical:7}} background="systemBlue" clipShape={{type:"capsule",style:"continuous"}}>✓ E-Hentai · 当前</Text>:<Button title="E-Hentai" buttonStyle="bordered" disabled={busy||account.eHentaiReachable!==true} action={() => { void run("e") }} />}{account.site === "ex"?<Text font="caption" foregroundStyle="white" padding={{horizontal:10,vertical:7}} background="systemBlue" clipShape={{type:"capsule",style:"continuous"}}>✓ ExHentai · 当前</Text>:account.exAvailable===true?<Button title="ExHentai" buttonStyle="bordered" disabled={busy} action={() => { void run("ex") }} />:<Button title="ExHentai · 未验证" buttonStyle="bordered" disabled action={()=>{}}/>}</HStack>{account.exAvailable!==true?<Text font="caption" foregroundStyle="secondaryLabel">ExHentai 尚无可验证的真实 Ex 域登录会话；请使用“同步里站登录”。</Text>:null}</VStack></Section>:null}
    <Section header={<Text textCase={null}>高级账户操作</Text>}><VStack alignment="leading" spacing={9}><Button title="从剪贴板导入 Cookie" disabled={busy} action={() => { void run("manual") }} /><Text font="caption" foregroundStyle="secondaryLabel">先在其他客户端复制 Cookie，再点此处直接读取原文。确认页只显示字段存在性：有有效 igneous → ExHentai；没有 igneous → E-Hentai。支持三行 `name: value` / `name=value`，也兼容换行被压平。</Text><Button title="刷新登录状态" disabled={busy || !account.loggedIn} action={() => { void run("refresh") }} />{account.loggedIn?<Button title="退出登录" role="destructive" disabled={busy} action={() => { void run("logout") }} />:null}</VStack></Section>
  </>
}

function AccountOverviewEntry({account}:{account:ReturnType<typeof getAccountStatus>}){const[data,setData]=useState<Awaited<ReturnType<typeof loadAccountOverview>>|null>(null),[loading,setLoading]=useState(false),[error,setError]=useState(""),[info,setInfo]=useState(""),epoch=useRef(0);const load=async()=>{const current=++epoch.current;if(!account.loggedIn){setData(null);setError("");setInfo("登录后可查看账户概览。");return}setLoading(true);setError("");setInfo("");try{const value=await loadAccountOverview();if(current===epoch.current)setData(value)}catch(caught){if(current===epoch.current)setError(caught instanceof Error?caught.message:String(caught))}finally{if(current===epoch.current)setLoading(false)}};useEffect(()=>{void load();return()=>{epoch.current+=1}},[account.loggedIn,account.site]);return <Section header={<Text textCase={null}>账户信息</Text>}><VStack alignment="leading" spacing={7}><HStack><Text font="headline">账户概览</Text><Spacer/><Button title="刷新" disabled={loading||!account.loggedIn} action={()=>void load()}/></HStack>{loading?<ProgressView progressViewStyle="circular"/>:null}{data?.imageLimitCurrent&&data.imageLimitMax?<Text>图片限额：{data.imageLimitCurrent} / {data.imageLimitMax}</Text>:null}{data?.resetCost?<Text font="caption" foregroundStyle="secondaryLabel">重置成本：{data.resetCost}</Text>:null}{data?.values.map(item=><Text key={item.label} font="caption" foregroundStyle="secondaryLabel">{item.label}：{item.value}</Text>)}{data&&!data.imageLimitCurrent&&!data.values.length?<Text font="caption" foregroundStyle="secondaryLabel">当前页面未提供可稳定显示的账户数据。</Text>:null}{info?<Text font="caption" foregroundStyle="secondaryLabel">{info}</Text>:null}{error?<ErrorText message={error}/>:null}</VStack></Section>}

function BuildMarker(){const[marker,setMarker]=useState("1.0.0-rc · 未同步");useEffect(()=>{let cancelled=false;void fileManager.readAsString(`${Script.directory}/sync-manifest.json`).then((text:string)=>{const value=JSON.parse(text),commit=String(value?.commit||"");if(!cancelled&&value?.version&&value?.branch&&commit)setMarker(`${value.version} · ${commit.slice(0,7)} · ${value.branch}`)}).catch(()=>{});return()=>{cancelled=true}},[]);return <Section header={<Text textCase={null}>开发与同步</Text>}><Text font="caption" foregroundStyle="secondaryLabel">构建：{marker}</Text></Section>}
export function AccountScene({onAccountChanged}:{onAccountChanged?:(status:ReturnType<typeof getAccountStatus>)=>void}={}){const[account,setAccount]=useState(getAccountStatus());const update=(status:ReturnType<typeof getAccountStatus>)=>{setAccount(status);onAccountChanged?.(status)};return <List navigationTitle="账号与设置" navigationBarTitleDisplayMode="inline"><AccountSection account={account} onAccountContextChanged={update}/><AccountOverviewEntry account={account}/><Section header={<Text textCase={null}>阅读偏好</Text>}><NavigationLink destination={<SettingsScene/>}><Text>阅读设置</Text></NavigationLink></Section><Section header={<Text textCase={null}>下载与缓存</Text>}><NavigationLink destination={<DownloadsScene/>}><Text>下载与离线阅读</Text></NavigationLink><NavigationLink destination={<CacheScene/>}><Text>图片缓存管理</Text></NavigationLink></Section><Section header={<Text textCase={null}>数据维护</Text>}><NavigationLink destination={<HistoryScene/>}><Text>历史记录与继续阅读</Text></NavigationLink><NavigationLink destination={<LibraryScene/>}><Text>打开完整书库</Text></NavigationLink></Section><BuildMarker/></List>}

function ContinueReadingStrip(){const[records,setRecords]=useState<Awaited<ReturnType<typeof loadHistory>>>([]),[selected,setSelected]=useState<GallerySummary|null>(null);useEffect(()=>{void loadHistory().then(setRecords).catch(()=>{})},[]);if(!records.length)return null;return <VStack alignment="leading" spacing={10} frame={{maxWidth:"infinity"}} navigationDestination={{isPresented:Boolean(selected),onChanged:presented=>{if(!presented)setSelected(current=>selectGallery(current,null))},content:selected?<GalleryDetailView summary={selected}/>:<VStack/>}}><Text font="headline">继续阅读</Text><ScrollView axes="horizontal"><HStack spacing={8}>{records.slice(0,8).map(record=>{const item=historySummary(record),progress=record.lastPageIndex!=null&&item.pages?Math.min(1,(record.lastPageIndex+1)/item.pages):0;return <Button key={`${record.gid}:${record.token}`} buttonStyle="plain" action={()=>setSelected(current=>selectGallery(current,item))}><GlassSurface padding={7}><HStack spacing={9}>{item.thumb?<CachedThumbnail url={item.thumb} stage="home-thumbnail" frame={{width:76,height:102}} cornerRadius={8}/>:<Image systemName="photo" frame={{width:76,height:102}} foregroundStyle="secondaryLabel"/>}<VStack alignment="leading" spacing={6} frame={{width:190}}><Text font="subheadline" lineLimit={2}>{item.title}</Text><ProgressView value={progress}/><Text font="caption" foregroundStyle="secondaryLabel">第 {(record.lastPageIndex??0)+1} 页{item.pages?` / ${item.pages}`:""}</Text></VStack></HStack></GlassSurface></Button>})}</HStack></ScrollView></VStack>}

export function HomeScene() {
  const dismiss = Navigation.useDismiss()
  const [account, setAccount] = useState(getAccountStatus())
  const [keyword, setKeyword] = useState("")
  const [items, setItems] = useState<GallerySummary[]>([])
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState("")
  const requestEpoch = useRef(0)
  const loadHome = async () => { const epoch = ++requestEpoch.current; setLoading(true); setError(""); try { const page = await searchGalleries("", getBaseUrl()); if (epoch === requestEpoch.current) setItems(page.items) } catch (caught) { if (epoch === requestEpoch.current) setError(caught instanceof Error ? caught.message : String(caught)) } finally { if (epoch === requestEpoch.current) setLoading(false) } }
  useEffect(() => { void loadHome(); void ensureTagTranslations(); return () => { requestEpoch.current += 1 } }, [])
  const searchState = createHomeSearchState(keyword)
  return <ScrollView navigationTitle="发现" navigationBarTitleDisplayMode="large" refreshable={loadHome} toolbar={{ cancellationAction: <Button title="关闭" action={dismiss} /> }} overlay={loading && !items.length ? <ProgressView title="正在加载画廊…" progressViewStyle="circular" /> : undefined} background={<PageBackground/>}><VStack alignment="leading" spacing={22} padding={{horizontal:16,vertical:14}} frame={{maxWidth:"infinity"}}><VStack alignment="leading" spacing={8} frame={{maxWidth:"infinity"}}><Text font="title" fontWeight="bold">发现</Text><Text font="caption" foregroundStyle="secondaryLabel">{account.site === "ex" ? "ExHentai" : "E-Hentai"} · 搜索、分类与最近阅读</Text></VStack><GlassSurface><SearchComposer initial={searchState}/></GlassSurface><VStack alignment="leading" spacing={10} frame={{maxWidth:"infinity"}}><Text font="headline">发现</Text><LazyVGrid columns={[{size:{type:"adaptive",min:150,max:260}}]} alignment="leading" spacing={10}><NavigationLink destination={<ResultsView initial={createPopularSearchState()}/>}><GlassSurface><Text font="headline">🔥 热门画廊</Text></GlassSurface></NavigationLink><NavigationLink destination={<ImageSearchScene/>}><GlassSurface><Text font="headline">🖼️ 图片搜索</Text></GlassSurface></NavigationLink><NavigationLink destination={<DiscoveryScene/>}><GlassSurface><Text font="headline">📊 排行榜与订阅</Text></GlassSurface></NavigationLink><NavigationLink destination={<ResultsView initial={createHomeSearchState()}/>}><GlassSurface><Text font="headline">🕘 最近更新</Text></GlassSurface></NavigationLink></LazyVGrid></VStack><VStack alignment="leading" spacing={10} frame={{maxWidth:"infinity"}}><Text font="headline">分类浏览</Text><ScrollView axes="horizontal"><HStack spacing={8}>{GALLERY_CATEGORIES.map(item=><NavigationLink key={item.key} destination={<ResultsView initial={createHomeSearchState("",item.key,"none")}/>}><Text padding={{horizontal:12,vertical:7}} background="secondarySystemBackground" clipShape={{type:"capsule",style:"continuous"}}>{item.shortLabel}</Text></NavigationLink>)}</HStack></ScrollView></VStack><ContinueReadingStrip/><VStack alignment="leading" spacing={10} frame={{maxWidth:"infinity"}}><HStack><Text font="headline">最新画廊</Text><Spacer/>{loading?<ProgressView progressViewStyle="circular"/>:null}</HStack>{error?<ErrorText message={error}/>:null}{error?<Button title="重试加载" buttonStyle="bordered" action={()=>void loadHome()}/>:null}{!loading&&!error&&!items.length?<EmptyState message="暂时没有可显示的画廊，稍后重试。"/>:null}<GalleryGrid items={items}/></VStack><VStack alignment="leading" spacing={8}><Text font="headline">更多</Text><HStack spacing={12}><Button title={account.loggedIn?"账号与设置":"登录与设置"} action={()=>void Navigation.present({element:<NavigationStack><AccountScene onAccountChanged={status=>{setAccount(status);void loadHome()}}/></NavigationStack>})}/><Button title="新闻" action={()=>void openExternalDestination("news").catch(setError)}/><Button title="论坛" action={()=>void openExternalDestination("forums").catch(setError)}/></HStack></VStack></VStack></ScrollView>
}

