function TorrentListScene({torrentUrl,sourceUrl}:{torrentUrl:string;sourceUrl:string}) { const [items,setItems]=useState<Array<{name:string;posted:string;downloadUrl:string}>>([]),[loading,setLoading]=useState(true),[error,setError]=useState("");useEffect(()=>{let cancelled=false;void loadTorrentList(torrentUrl,sourceUrl).then(value=>{if(!cancelled)setItems(value)}).catch(value=>{if(!cancelled)setError(value instanceof Error?value.message:"种子列表读取失败。")}).finally(()=>{if(!cancelled)setLoading(false)});return()=>{cancelled=true}},[torrentUrl,sourceUrl]);return <ScrollView navigationTitle="种子列表" navigationBarTitleDisplayMode="inline"><VStack alignment="leading" spacing={14} padding={{horizontal:16,vertical:12}} frame={{maxWidth:760,alignment:"leading"}}>{loading?<ProgressView title="读取种子列表…" progressViewStyle="circular"/>:null}{error?<ErrorText message={error}/>:null}{!loading&&!error&&!items.length?<Text foregroundStyle="secondaryLabel">服务器未返回可用种子。</Text>:null}{items.map((item,index)=><VStack key={item.downloadUrl} alignment="leading" spacing={4} frame={{maxWidth:"infinity"}}><Text>{item.name}</Text>{item.posted?<Text font="caption" foregroundStyle="secondaryLabel">{item.posted}</Text>:null}<Button title="在 Safari 下载" buttonStyle="bordered" action={()=>void openResource(item.downloadUrl)}/></VStack>)}<VStack alignment="leading" spacing={6} frame={{maxWidth:"infinity"}}><Text font="caption" foregroundStyle="secondaryLabel">若列表无法读取，可在系统浏览器打开原始种子页面。</Text><Button title="在 Safari 打开种子页面" buttonStyle="bordered" action={()=>void openResource(torrentUrl)}/></VStack></VStack></ScrollView> }

function ArchiveOptionsScene({archiveUrl,sourceUrl}:{archiveUrl:string;sourceUrl:string}){const[items,setItems]=useState<Array<{name:string;resolution:string;original:boolean;requestOr:string}>>([]),[loading,setLoading]=useState(true),[busy,setBusy]=useState(""),[error,setError]=useState("");useEffect(()=>{let cancelled=false;void loadArchiveOptions(archiveUrl,sourceUrl).then(value=>{if(!cancelled)setItems(value)}).catch(value=>{if(!cancelled)setError(value instanceof Error?value.message:"归档选项读取失败。")}).finally(()=>{if(!cancelled)setLoading(false)});return()=>{cancelled=true}},[archiveUrl,sourceUrl]);const download=async(item:typeof items[number])=>{setBusy(item.resolution);setError("");try{await openResource(await resolveArchiveDownload(archiveUrl,sourceUrl,item))}catch(value){setError(value instanceof Error?value.message:"归档下载请求失败。")}finally{setBusy("")}};return <List navigationTitle="归档选项"><Section>{loading?<ProgressView title="读取归档选项…" progressViewStyle="circular"/>:null}{error?<ErrorText message={error}/>:null}{items.map(item=><VStack key={item.resolution} alignment="leading" spacing={4}><Text>{item.name}</Text><Text font="caption" foregroundStyle="secondaryLabel">{item.original?"原始图像归档":"重采样归档"}</Text><Button title={busy===item.resolution?"正在请求…":"下载此归档"} buttonStyle="borderedProminent" disabled={Boolean(busy)} action={()=>void download(item)}/></VStack>)}{!loading&&!error&&!items.length?<EmptyState message="未读取到归档选项，可能受到服务器额度或权限限制。"/>:null}<Button title="在 Safari 打开归档页" action={()=>void openResource(archiveUrl)}/></Section></List>}
function CommentCard({comment,busy,onVote,onEdit}:{comment:GalleryDetail["comments"][number];busy:boolean;onVote:(comment:GalleryDetail["comments"][number],value:1|-1)=>void;onEdit:(comment:GalleryDetail["comments"][number])=>void}){return <GlassSurface><VStack alignment="leading" spacing={9} frame={{maxWidth:"infinity"}}><HStack spacing={10} frame={{maxWidth:"infinity"}}><Text font="subheadline" fontWeight="semibold">{comment.author||"匿名用户"}</Text><Spacer/>{comment.posted?<Text font="caption" foregroundStyle="secondaryLabel">{comment.posted}</Text>:null}</HStack><Text frame={{maxWidth:"infinity",alignment:"leading"}}>{comment.text}</Text>{comment.id?<HStack spacing={10} frame={{maxWidth:"infinity",alignment:"leading"}}><Text font="caption" foregroundStyle="secondaryLabel">评分 {comment.score}</Text>{comment.canVoteUp?<Button title={comment.voted===1?"取消赞同":"赞同"} disabled={busy} action={()=>onVote(comment,1)}/>:null}{comment.canVoteDown?<Button title={comment.voted===-1?"取消反对":"反对"} disabled={busy} action={()=>onVote(comment,-1)}/>:null}{comment.canEdit?<Button title="编辑" disabled={busy} action={()=>onEdit(comment)}/>:null}</HStack>:null}</VStack></GlassSurface>}
function CommentsScene({detail,onChanged}:{detail:GalleryDetail;onChanged:(comments:GalleryDetail["comments"])=>void}) {const[comments,setComments]=useState(detail.comments),[busy,setBusy]=useState(false),[error,setError]=useState("");const apply=(value:GalleryDetail["comments"])=>{setComments(value);onChanged(value)};const create=async()=>{const text=await prompt({title:"发表评论",message:"评论将提交到当前画廊。",placeholder:"输入评论",confirmLabel:"继续"});if(!text)return;if(!await confirm({title:"确认发表评论？",message:"此操作会修改服务器数据。",confirmLabel:"发表",cancelLabel:"取消"}))return;setBusy(true);setError("");try{apply(await submitGalleryComment(detail,text))}catch(e){setError(e instanceof Error?e.message:"评论提交失败")}finally{setBusy(false)}};const edit=async(comment:GalleryDetail["comments"][number])=>{setBusy(true);setError("");try{const editable=await loadEditableGalleryComment(detail,comment.id),text=await prompt({title:"编辑评论",message:"修改自己的评论。",placeholder:editable.text||comment.text,confirmLabel:"继续"});if(text==null)return;if(!await confirm({title:"确认保存修改？",message:"此操作会修改服务器数据。",confirmLabel:"保存",cancelLabel:"取消"}))return;apply(await submitGalleryComment(detail,text,comment.id))}catch(e){setError(e instanceof Error?e.message:"评论编辑失败")}finally{setBusy(false)}};const vote=async(comment:GalleryDetail["comments"][number],value:1|-1)=>{if(!await confirm({title:value===1?"赞同这条评论？":"反对这条评论？",message:"再次提交相同方向可由服务器取消现有投票。",confirmLabel:"提交",cancelLabel:"取消"}))return;setBusy(true);setError("");try{const result=await voteGalleryComment(detail,comment.id,value);apply(comments.map(item=>item.id===result.id?{...item,score:result.score,voted:result.voted}:item))}catch(e){setError(e instanceof Error?e.message:"评论投票失败")}finally{setBusy(false)}};return <ScrollView navigationTitle={`评论 · ${comments.length}`} navigationBarTitleDisplayMode="inline"><VStack alignment="leading" spacing={12} padding={{horizontal:20,vertical:14}} frame={{maxWidth:"infinity"}}><HStack frame={{maxWidth:"infinity"}}><Button title="发表评论" buttonStyle="borderedProminent" disabled={busy} action={()=>void create()}/><Spacer/></HStack>{error?<ErrorText message={error}/>:null}{comments.map((comment,index)=><CommentCard key={`${comment.id}-${index}`} comment={comment} busy={busy} onVote={(item,value)=>void vote(item,value)} onEdit={item=>void edit(item)}/>)}</VStack></ScrollView> }

function InfoRow({label,value}:{label:string;value:string}){if(!String(value||"").trim())return null;return <HStack alignment="top" spacing={12} frame={{maxWidth:"infinity"}}><Text font="caption" foregroundStyle="secondaryLabel" frame={{width:92,alignment:"leading"}}>{label}</Text><Text font="subheadline" frame={{maxWidth:"infinity",alignment:"trailing"}}>{value}</Text></HStack>}
const PREVIEW_SUMMARY_LIMIT=18
const MOBILE_PREVIEW_LIMIT=6
export const MOBILE_DETAIL_SECTION_ORDER=["hero","reading","actions","preview","tags","basic","resources","related"] as const
export function previewSummaryPages<T>(pages:T[],limit=PREVIEW_SUMMARY_LIMIT){return pages.slice(0,Math.max(0,limit))}
export function mobilePreviewSummaryPages<T>(pages:T[]){return previewSummaryPages(pages,MOBILE_PREVIEW_LIMIT)}
export function previewNeedsMore(loaded:number,total:number,visibleIndex:number){return loaded<total&&visibleIndex>=Math.max(0,loaded-3)}
export function previewPageRangeForIndexes(first:number,last:number,totalPages:number,previewPages:number){const start=Math.max(0,Math.floor((Math.max(1,first)-1)/20)),end=Math.min(Math.max(0,previewPages-1),Math.floor((Math.max(1,last)-1)/20));return{start:Math.min(start,end),end:Math.max(start,end)}}
export function selectedPreviewPages(pages:GalleryPageLink[],selected:ReadonlySet<number>){return pages.filter(page=>selected.has(page.index)).map(page=>({index:page.index,pageUrl:page.pageUrl}))}
export function selectionModeAfterDone(){return false}
export function downloadSelectionSnapshot(pages:GalleryPageLink[],selected:ReadonlySet<number>){return selectedPreviewPages(pages,new Set(selected))}
export type SelectionGestureMode="select"|"deselect"|null
export function dragSelectionTarget(anchor:number,translation:{x?:number;y?:number},columns:number,count:number){const row=Math.round(Number(translation.y||0)/164),column=Math.round(Number(translation.x||0)/128);return Math.max(0,Math.min(Math.max(0,count-1),anchor+row*Math.max(1,columns)+column))}
export function applySelectionGesture(selected:ReadonlySet<number>,pages:GalleryPageLink[],anchor:number,target:number,mode:SelectionGestureMode,visited:ReadonlySet<number>){const next=new Set(selected),handled=new Set(visited),start=Math.max(0,Math.min(anchor,target)),end=Math.min(pages.length-1,Math.max(anchor,target));for(let index=start;index<=end;index+=1){const page=pages[index];if(!page||handled.has(page.index))continue;handled.add(page.index);if(mode==="select")next.add(page.index);else if(mode==="deselect")next.delete(page.index)}return{selected:next,visited:handled}}
type PreviewDownloadState={id:string;scope:"all"|"partial";pages:Array<{index:number;pageUrl:string}>;done:number[];libraryDone:number[];photosDone:number[];photosPending:number[];failed:number[];status:string;destination:OfflineDownloadDestination;totalPages:number}
function downloadDestinationLabel(destination:OfflineDownloadDestination){return destination==="both"?"离线书库 + 系统图库":destination==="photos"?"系统图库":"离线书库"}
export function photosProgressLabel(item:Pick<PreviewDownloadState,"destination"|"photosDone"|"pages">){return item.destination==="photos"||item.destination==="both"?`正在保存到图库 ${item.photosDone.length} / ${item.pages.length}`:""}
