function ReaderProgressOverlay({index,count,playing,onJump,onToggle,onClose,onOriginal}:{index:number;count:number;playing:boolean;onJump:(index:number)=>void;onToggle:()=>void;onClose:()=>void;onOriginal?:()=>void}){const[value,setValue]=useState(index+1);useEffect(()=>setValue(index+1),[index]);return <GlassSurface padding={12}><VStack alignment="leading" spacing={8} frame={{maxWidth:"infinity"}}><HStack><Text font="headline">{index+1} / {count}</Text><Spacer/><Button title={playing?"暂停":"播放"} systemImage={playing?"pause.fill":"play.fill"} action={onToggle}/><Button title="关闭" systemImage="xmark" action={onClose}/></HStack><Slider value={value} min={1} max={Math.max(1,count)} step={1} onChanged={setValue} onEditingChanged={editing=>{if(!editing)onJump(Math.round(value)-1)}} label={<Text>阅读进度</Text>}/><HStack><Button title="跳至当前页码" buttonStyle="bordered" action={()=>onJump(Math.round(value)-1)}/>{onOriginal?<Button title="查看原图" buttonStyle="bordered" action={onOriginal}/>:null}</HStack></VStack></GlassSurface>}
function ReaderTapZones({direction,onAction,disabled=false}:{direction:ReaderPreferences["direction"];onAction:(action:ReaderTapAction)=>void;disabled?:boolean}){const zone=(value:ReaderTapZone)=><Button buttonStyle="plain" disabled={disabled} action={()=>onAction(readerTapAction(value,direction))} frame={{maxWidth:"infinity",maxHeight:"infinity"}} contentShape={{type:"rect",cornerRadius:0}}><Rectangle fill="rgba(0,0,0,0.001)" frame={{maxWidth:"infinity",maxHeight:"infinity"}}/></Button>;return <HStack spacing={0} frame={{maxWidth:"infinity",maxHeight:"infinity"}}>{zone("left")}<VStack spacing={0} frame={{maxWidth:"infinity",maxHeight:"infinity"}}>{zone("centerUpper")}{zone("centerLower")}</VStack>{zone("right")}</HStack>}

export type ReaderZoomState={scale:number;offset:{x:number;y:number}}
export function clampReaderScale(value:number){return Math.max(1,Math.min(4,value))}
export function readerZoomed(scale:number){return scale>1.05}
